        /// Budget (in USD) applied to each individual team member.
        /// </summary>
        [Input("teamMemberBudget")]
        public Input<double>? TeamMemberBudget { get; set; }

        /// <summary>
        /// Reset cycle for the per-member budget (e.g. `30d`, `1mo`).
        /// </summary>
        [Input("teamMemberBudgetDuration")]
        public Input<string>? TeamMemberBudgetDuration { get; set; }

        /// <summary>
        /// Lifetime for keys created by team members (e.g. `1d`, `1w`).
        /// </summary>
        [Input("teamMemberKeyDuration")]
        public Input<string>? TeamMemberKeyDuration { get; set; }

        /// <summary>
        /// JSON string of per-model budgets applied to each individual team member, e.g. `jsonencode({"claude-opus" = {budget_limit = 400, TimePeriod = "1d"}})`. Each model maps to an object with `BudgetLimit` (or `MaxBudget`) and `TimePeriod` (or `BudgetDuration`). The proxy rejects `TpmLimit` and `RpmLimit` on team budgets, so the provider rejects them at plan time. A member who reaches a model's cap is blocked on that model only and can keep calling the team's other models until `TeamMemberBudget` runs out. The key is matched against the model name on the request, so for a router alias the cap applies to the alias, not the model the router picks. Remove the attribute to clear every per-model member budget. Requires a LiteLLM Enterprise license on the proxy, and a proxy that includes [#43887](https://github.com/BerriAI/litellm/pull/43887). Older proxies, including v1.105.0 and v1.106.0-rc.1, accept the field but silently drop it, so every plan shows a diff.
        /// </summary>
        [Input("teamMemberModelMaxBudget")]
        public Input<string>? TeamMemberModelMaxBudget { get; set; }

